// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address nonOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != c.owner());
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != c.owner());

        vm.prank(nonOwner);
        bool ok = true;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || c.owner() != newOwner);
    }
}
